cy.visitTodos([]);
const times = [];
for (let k = 0; k < 10; k++) {
  cy.window({
    log: false
  }).then(w => {
    const input = w.document.querySelector('.new-todo');
    input.value = `perf ${k}`;
    const t0 = w.performance.now();
    input.dispatchEvent(new w.KeyboardEvent('keypress', {
      keyCode: 13,
      which: 13,
      bubbles: true
    }));
    input.dispatchEvent(new w.KeyboardEvent('keyup', {
      keyCode: 13,
      which: 13,
      bubbles: true
    }));
    input.dispatchEvent(new w.Event('change', {
      bubbles: true
    }));
    times.push(w.performance.now() - t0);
  });
}
cy.get('.todo-list li').should('have.length.at.least', 1).then(() => {
  const sorted = [...times].sort((a, b) => a - b);
  const median = sorted[Math.floor(sorted.length / 2)];
  cy.task('evidence', {
    kind: 'perf',
    record: {
      page: '/todo add-latency',
      samplesMs: times,
      medianMs: median
    }
  });
  expect(median, 'median add latency (ms)').to.be.lessThan(100);
});

cy.visitPage('/commands/actions', {
  onBeforeLoad(w) {
    w.__long = [];
    try {
      new w.PerformanceObserver(l => l.getEntries().forEach(e => w.__long.push(e.duration))).observe({
        type: 'longtask',
        buffered: true
      });
    } catch (_e) {
      w.__long = null;
    }
  }
});
cy.wait(500);
cy.window().its('__long').then(list => {
  if (list === null) {
    cy.log('longtask API not supported in this browser');
    return;
  }
  cy.task('evidence', {
    kind: 'perf',
    record: {
      page: '/commands/actions longtasks',
      durations: list
    }
  });
  expect(Math.max(0, ...list), 'longest task (ms)').to.be.lessThan(200);
});
